import React, { useRef, useEffect, useCallback } from 'react';
import CardContent from '@mui/material/CardContent';
import CardActions from '@mui/material/CardActions';
import Grid from '@mui/material/Grid';
import Card from '@mui/material/Card';
import { getMimeType, getUrl, thumbThick } from '../lib/utils';
import { FadeSettings } from '../types';
import VolumeBar from './VolumeBar';
import ControlKeys from './ControlKeys';
import MediaTime from './MediaTime';
import Progress from './Progress';
import SpeedBar from './SpeedBar';
import { styled, useTheme } from '@mui/material/styles';
import { State } from '../state/types';
import { MaterialUIMediaProps } from '../types';
import { useMedia } from '../hooks';

const StyledCard = styled(Card, {
    shouldForwardProp: (prop) => prop !== 'background',
})<{ background?: string }>(({ background }) => ({
    display: 'flex',
    flexDirection: 'column',
    backgroundColor: background || 'inherit',
}));

const StyledCardContent = styled(CardContent)({
    display: 'flex',
    justifyContent: 'center',
});

const VideoContainer = styled('div')(({ theme }) => ({
    backgroundColor: theme.palette.common.black,
    display: 'inline-block',
}));

const StyledVideo = styled('video', {
    shouldForwardProp: (prop) => prop !== 'videoWidth' && prop !== 'videoHeight',
})<{ videoWidth?: number; videoHeight?: number }>(({ videoWidth, videoHeight }) => ({
    width: videoWidth,
    height: videoHeight,
}));

const StyledCardActions = styled(CardActions)(({ theme }) => ({
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    '&:last-child': {
        paddingBottom: theme.spacing(1),
    },
}));

const ControlsGrid = styled(Grid)(({ theme }) => ({
    display: 'flex',
    flexDirection: 'row',
    alignItems: 'center',
    [theme.breakpoints.down('md')]: {
        justifyContent: 'space-between',
        flexGrow: 1,
    },
    [theme.breakpoints.up('md')]: {
        justifyContent: 'start',
    },
}));

const BarsGrid = styled(Grid)(({ theme }) => ({
    display: 'flex',
    flexDirection: 'row',
    alignItems: 'center',
    [theme.breakpoints.down('md')]: {
        justifyContent: 'space-between',
        flexGrow: 1,
    },
    [theme.breakpoints.up('md')]: {
        justifyContent: 'start',
    },
}));

export interface VideoCardProps extends MaterialUIMediaProps {
    fadeSettings?: FadeSettings;
}

const getInitialState = (props: VideoCardProps): State => ({
    url: '',
    key: Math.random(),
    playing: false,
    time: {
        currentTime: 0,
        duration: 0,
    },
    fade: 1,
    width: props.width,
    height: (props.width || 0) * 9 / 16,
    playerTimeout: null,
    src: props.src,
});

const VideoCard = (props: VideoCardProps) => {
    const { color = 'primary', thickness = 'medium' } = props;
    const player: React.MutableRefObject<HTMLVideoElement> = useRef(null!);
    const { state, pause, setSize, load, play, stop, setCurrentTime, setProgress } = useMedia(getInitialState(props), props.fadeSettings);
    const theme = useTheme();

    const {
        onEnded = () => setCurrentTime(player.current, 0),
        onBackwardClick = () => { },
        onForwardClick = () => { },
        loop = !!props.loop,
        autoplay = !!props.autoplay,
    } = props;
    const onPlay = useCallback(async () => {
        if (!player.current.src) {
            const videoUrl = await getUrl(props.src);
            load(player.current, videoUrl);
            await new Promise<void>((resolve) => {
                player.current.onloadedmetadata = () => {
                    setSize(player.current);
                    resolve();
                };
            });
        }

        await play(player.current);
    }, [props.src, load, play, setSize]);

    useEffect(() => {
        player.current.autoplay = autoplay;
        player.current.loop = loop;
        player.current.onended = () => {
            pause(player.current);
            onEnded();
        };
    }, [pause, onEnded, autoplay, loop]);

    useEffect(() => {
        autoplay && onPlay();
    }, [autoplay, onPlay]);

    return (
        <StyledCard background={props.background}>
            <StyledCardContent>
                <VideoContainer>
                    <StyledVideo
                        style={{ opacity: state.fade }}
                        ref={player}
                        key={state.key}
                        videoWidth={state.width}
                        videoHeight={state.height}
                    >
                        {state.url && <source type={getMimeType(state.url)} src={state.url} />}
                    </StyledVideo>
                </VideoContainer>
            </StyledCardContent>
            <StyledCardActions sx={{
                paddingTop: theme.spacing(1),
                paddingRight: theme.spacing(2),
                paddingLeft: `calc(${thumbThick[thickness]/2}px + ${theme.spacing(2)})`,
                paddingBottom: theme.spacing(1),
            }}>
                <Grid
                    container
                    sx={{ width: '100%', justifyContent: 'center', alignItems: 'center' }}
                >
                    <Grid
                        size={12}
                    >
                        <Progress
                            time={state.time}
                            color={color}
                            thickness={thickness}
                            onProgressClick={async v => await setProgress(player.current, v)}
                        />
                    </Grid>
                    <ControlsGrid
                        size={{ xs: 12, md: 6 }}
                    >
                        <MediaTime
                            time={state.time}
                            TimeProps={props.TimeProps}
                        />
                        <ControlKeys
                            onPauseClick={() => pause(player.current)}
                            onPlayClick={onPlay}
                            backward={props.backward}
                            forward={props.forward}
                            playing={state.playing}
                            onForwardClick={onForwardClick}
                            onBackwardClick={onBackwardClick}
                            onStopClick={() => stop(player.current)}
                            color={color}
                            BackwardProps={props.BackwardProps}
                            StopProps={props.StopProps}
                            PauseProps={props.PauseProps}
                            PlayProps={props.PlayProps}
                            ForwardProps={props.ForwardProps}
                        />
                    </ControlsGrid>
                    <BarsGrid
                        size={{ xs: 12, md: 6 }}
                    >
                        {props.speed &&
                            <SpeedBar
                                player={player.current}
                                color={color}
                                thickness={thickness}
                            />
                        }
                        <VolumeBar
                            player={player.current}
                            color={color}
                            thickness={thickness}
                            mute={props.mute}
                            MuteProps={props.MuteProps}
                        />
                    </BarsGrid>
                </Grid>
            </StyledCardActions>
        </StyledCard>
    );
}

export default VideoCard;